def gravity(g):
    h,w=len(g),len(g[0])
    objs=comps(g)
    # static = border-colored cells (color forming full rows/cols?) Here treat cells not part of moved objects: cells with color that spans a full row or col
    # determine border color: a color occupying an entire row or column
    border=None
    colors={v for r in g for v in r}
    for c in colors:
        if any(all(v==c for v in r) for r in g) or any(all(r[j]==c for r in g) for j in range(w)):
            border=c
    moved=[(c,cells) for c,cells in objs if c!=border]
    static=[(i,j) for i in range(h) for j in range(w) if g[i][j]==border]
    # iteratively move each object down 1 (toward border direction)
    # direction: find which side border is on (row border): if border row is last, gravity down; if first, up
    brow=[i for i in range(h) if all(g[i][j]==border for j in range(w))]
    bcol=[j for j in range(w) if all(g[i][j]==border for i in range(h))]
    if brow and max(brow)==h-1: d=(1,0)
    elif brow and min(brow)==0: d=(-1,0)
    elif bcol and max(bcol)==w-1: d=(0,1)
    else: d=(0,-1)
    def blocked(cells):
        s=set(cells)
        for a,b in cells:
            x,y=a+d[0],b+d[1]
            if not(0<=x<h and 0<=y<w): return True
            if (x,y) in static or (x,y) in s: continue
            if g[x][y]!=0 and g[x][y]!=c and (x,y) not in s:
                # occupied by another object cell
                if any((x,y) in oc for _,oc in moved): return True
        return False
    changed=True
    while changed:
        changed=False
        for c,cells in moved:
            can=True
            for a,b in cells:
                x,y=a+d[0],b+d[1]
                if not(0<=x<h and 0<=y<w) or ((x,y) in static): can=False;break
                if (x,y) in cells: continue
                if g[x][y]!=0 and not any((x,y) in oc for oc2,oc in moved if oc2!=c): pass
                occ=any((x,y) in oc for oc2,oc in moved if oc2!=c)
                if occ: can=False;break
            if can:
                for a,b in cells: g[a][b]=0
                nc=[(a+d[0],b+d[1]) for a,b in cells]
                for a,b in nc: g[a][b]=c
                cells[:]=nc
                changed=True
    return g

